diff --git a/crates/rrx/src/state/mod.rs b/crates/rrx/src/state/mod.rs
index 7af6f76..cbd960a 100644
--- a/crates/rrx/src/state/mod.rs
+++ b/crates/rrx/src/state/mod.rs
@@ -1447,7 +1447,14 @@ fn str_id<T: std::fmt::Display>(id: Option<T>) -> Option<String> {
 }
 fn validate_goal_references(tx: &Transaction<'_>, goal: &Goal) -> Result<()> {
     use std::collections::BTreeSet;
-    let mut references: BTreeSet<_> = goal.dag.hard_order()?.into_iter().collect();
+    let mut references: BTreeSet<_> = match read_tx::<Goal>(tx, "goals", &goal.id.to_string())? {
+        Some(previous)
+            if serde_json::to_value(&previous.dag)? == serde_json::to_value(&goal.dag)? =>
+        {
+            goal.dag.nodes.iter().copied().collect()
+        }
+        _ => goal.dag.hard_order()?.into_iter().collect(),
+    };
     for proposal in &goal.followups {
         references.extend(proposal.dependencies.iter().copied());
     }
